#include <bits/stdc++.h>
using namespace std;

int main() {
    string message, line;
    getline(cin, message);
    if (!message.empty() && message.back() == '\r') message.pop_back();
    getline(cin, line);
    long long n = stoll(line);
    const string consonants = "bcdfghjklmnpqrstvwxyz", vowels = "aeiouAEIOU";
    long long count = 0;
    for (char &ch : message) {
        char lower = tolower((unsigned char)ch);
        if (lower >= 'a' && lower <= 'z' && vowels.find(ch) == string::npos) {
            if (++count % n == 0) {
                // Next consonant in the cyclic consonant list, keeping the case.
                char shifted = consonants[(consonants.find(lower) + 1) % consonants.size()];
                ch = isupper((unsigned char)ch) ? toupper(shifted) : shifted;
            }
        }
    }
    cout << message << "\n";
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        char[] message = br.readLine().toCharArray();
        long n = Long.parseLong(br.readLine().trim());
        String consonants = "bcdfghjklmnpqrstvwxyz", vowels = "aeiouAEIOU";
        long count = 0;
        for (int i = 0; i < message.length; i++) {
            char ch = message[i], lower = Character.toLowerCase(ch);
            if (lower >= 'a' && lower <= 'z' && vowels.indexOf(ch) < 0 && ++count % n == 0) {
                // Next consonant in the cyclic consonant list, keeping the case.
                char shifted = consonants.charAt((consonants.indexOf(lower) + 1) % consonants.length());
                message[i] = Character.isUpperCase(ch) ? Character.toUpperCase(shifted) : shifted;
            }
        }
        System.out.print(new String(message) + "\n");
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
	"strings"
)

func main() {
	r := bufio.NewReaderSize(os.Stdin, 1<<20)
	line, _ := r.ReadString('\n')
	message := []byte(strings.TrimRight(line, "\r\n"))
	nLine, _ := r.ReadString('\n')
	n, _ := strconv.Atoi(strings.TrimSpace(nLine))
	const consonants = "bcdfghjklmnpqrstvwxyz"
	count := 0
	for i, ch := range message {
		lower := ch | 0x20
		isLetter := (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')
		if isLetter && !strings.ContainsRune("aeiou", rune(lower)) {
			count++
			if count%n == 0 {
				// Next consonant in the cyclic consonant list, keeping the case.
				shifted := consonants[(strings.IndexByte(consonants, lower)+1)%len(consonants)]
				if ch < 'a' {
					shifted -= 'a' - 'A'
				}
				message[i] = shifted
			}
		}
	}
	os.Stdout.Write(append(message, '\n'))
}
